async function getRunnerRecords(telegramId:string,env:Env){const best=await env.DB.prepare("SELECT COALESCE(MAX(distance),0) AS best_distance,COALESCE(MAX(points),0) AS best_points,COUNT(*) AS total_runs FROM runner_game_runs WHERE user_id=? AND status='completed'").bind(telegramId).first<{best_distance:number;best_points:number;total_runs:number}>();const recent=await env.DB.prepare("SELECT CAST(strftime('%s',completed_at) AS INTEGER)*1000 AS playedAt,distance,points,footballs AS balls FROM runner_game_runs WHERE user_id=? AND status='completed' ORDER BY completed_at DESC LIMIT 20").bind(telegramId).all<{playedAt:number;distance:number;points:number;balls:number}>();return {bestDistance:Number(best?.best_distance)||0,bestPoints:Number(best?.best_points)||0,totalRuns:Number(best?.total_runs)||0,recentRuns:recent.results.map(row=>({playedAt:Number(row.playedAt)||0,distance:Number(row.distance)||0,points:Number(row.points)||0,balls:Number(row.balls)||0}))};}

const bytesHex=(bytes:Uint8Array)=>Array.from(bytes,b=>b.toString(16).padStart(2,"0")).join("");
async function sha256Hex(value:string){return bytesHex(new Uint8Array(await crypto.subtle.digest("SHA-256",encoder.encode(value))));}
async function rateLimitIpHash(request:Request,env:Env){const ip=request.headers.get("cf-connecting-ip")||"unknown",pepper=env.ADMIN_SETUP_SECRET||env.TELEGRAM_BOT_TOKEN||env.MONETAG_POSTBACK_SECRET;if(!pepper)return sha256Hex(ip);const key=await crypto.subtle.importKey("raw",encoder.encode(pepper),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return bytesHex(new Uint8Array(await crypto.subtle.sign("HMAC",key,encoder.encode(ip))));}
async function passwordHash(password:string,saltHex:string,iterations:number){if(!/^(?:[a-f0-9]{2}){16}$/i.test(saltHex))throw new Error("invalid salt");const saltBytes=Uint8Array.from(saltHex.match(/.{2}/g)!,v=>parseInt(v,16));const passwordBytes=encoder.encode(password);const saltBuffer=saltBytes.buffer.slice(saltBytes.byteOffset,saltBytes.byteOffset+saltBytes.byteLength) as ArrayBuffer;const passwordBuffer=passwordBytes.buffer.slice(passwordBytes.byteOffset,passwordBytes.byteOffset+passwordBytes.byteLength) as ArrayBuffer;let key:CryptoKey;try{key=await crypto.subtle.importKey("raw",passwordBuffer,{name:"PBKDF2"},false,["deriveBits"]);}catch(e){const x=e as Error;throw new Error("PBKDF2 importKey "+(x.name||"Error")+": "+(x.message||"failed"));}let bits:ArrayBuffer;try{bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:saltBuffer,iterations},key,256);}catch(e){const x=e as Error;throw new Error("PBKDF2 deriveBits "+(x.name||"Error")+": "+(x.message||"failed"));}return bytesHex(new Uint8Array(bits));}
function cookieValue(request:Request,name:string){const raw=request.headers.get("cookie")||"";for(const part of raw.split(";")){const [k,...v]=part.trim().split("=");if(k===name)return v.join("=");}return "";}
function sameOrigin(request:Request){const origin=request.headers.get("origin");return !!origin&&origin===new URL(request.url).origin;}
async function createAdminSession(env:Env,adminId:number){const random=new Uint8Array(32);crypto.getRandomValues(random);const token=bytesHex(random),tokenHash=await sha256Hex(token),expires=new Date(Date.now()+7*24*60*60*1000).toISOString();await env.DB.prepare("INSERT INTO admin_sessions (token_hash,admin_id,expires_at) VALUES (?,?,?)").bind(tokenHash,adminId,expires).run();return token;}
async function editorialAdmin(request:Request,env:Env):Promise<string|null>{const token=cookieValue(request,"st_admin");if(!token||token.length!==64)return null;try{const tokenHash=await sha256Hex(token);const session=await env.DB.prepare("SELECT s.admin_id FROM admin_sessions s JOIN admin_users a ON a.id=s.admin_id WHERE s.token_hash=? AND julianday(s.expires_at)>julianday('now')").bind(tokenHash).first<{admin_id:number}>();return session?String(session.admin_id):null;}catch{return null;}}
async function editorialStaff(request:Request,env:Env):Promise<{telegramId:string;role:"host"|"editor"}|null>{const telegramId=await authenticatedUser(request,env);if(!telegramId)return null;try{const row=await env.DB.prepare("SELECT role FROM editorial_staff WHERE telegram_user_id=? AND status='active'").bind(telegramId).first<{role:"host"|"editor"}>();return row?{telegramId,role:row.role}:null;}catch{return null;}}
const textField=(v:unknown,max:number)=>typeof v==='string'?v.trim().slice(0,max):'';
const SOCIAL_TASK_HOSTS:Record<string,string[]>={telegram_channel:["t.me","telegram.me"],facebook_follow:["facebook.com","www.facebook.com","m.facebook.com","fb.com","www.fb.com"],whatsapp_community:["chat.whatsapp.com","whatsapp.com","www.whatsapp.com","wa.me"]};
function validateSocialTaskDestination(taskKey:string,value:unknown):{valid:boolean;url:string|null}{if(value===null||value==="")return {valid:true,url:null};if(typeof value!=="string"||value.length>2048)return {valid:false,url:null};const normalized=secureUrl(value);if(!normalized)return {valid:false,url:null};try{const parsed=new URL(normalized);if(parsed.username||parsed.password||parsed.port||!SOCIAL_TASK_HOSTS[taskKey]?.includes(parsed.hostname.toLowerCase()))return {valid:false,url:null};return {valid:true,url:normalized};}catch{return {valid:false,url:null};}}
async function awardReferralMilestones(inviterId:string,qualifiedCount:number,env:Env){
 const milestones=await env.DB.prepare("SELECT milestone_number,qualified_threshold,reward_amount,title FROM referral_milestone_catalogue WHERE enabled=1 AND qualified_threshold<=? ORDER BY qualified_threshold ASC").bind(qualifiedCount).all<{milestone_number:number;qualified_threshold:number;reward_amount:number;title:string}>();
 for(const milestone of milestones.results){
  const threshold=Number(milestone.qualified_threshold),amount=Number(milestone.reward_amount),number=Number(milestone.milestone_number);
  if(!Number.isSafeInteger(threshold)||!Number.isSafeInteger(amount)||amount<=0)continue;
  const rewardKey="referral-milestone:"+inviterId+":"+threshold;
  const description="Referral milestone: "+threshold.toLocaleString()+" qualified members";
  const body="You reached "+threshold.toLocaleString()+" qualified referrals and earned "+amount.toLocaleString()+" SETHIS.";
  await env.DB.batch([
   env.DB.prepare("INSERT OR IGNORE INTO wallets(user_id,ct_balance,sethis_balance) VALUES(?,0,0)").bind(inviterId),
   env.DB.prepare("INSERT OR IGNORE INTO wallet_ledger(id,user_id,token,amount,transaction_type,reference_id,idempotency_key,grant_source,grant_reason) VALUES(?,?,'SETHIS',?,'referral_reward',?,?,'referral',?)").bind(id(),inviterId,amount,rewardKey,rewardKey,description),
   env.DB.prepare("UPDATE wallets SET sethis_balance=sethis_balance+?,updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND EXISTS(SELECT 1 FROM wallet_ledger WHERE idempotency_key=?) AND NOT EXISTS(SELECT 1 FROM referral_rewards WHERE ledger_key=?)").bind(amount,inviterId,rewardKey,rewardKey),
   env.DB.prepare("INSERT OR IGNORE INTO referral_rewards(id,inviter_user_id,milestone,amount,ledger_key) VALUES(?,?,?,?,?)").bind(id(),inviterId,threshold,amount,rewardKey),
   env.DB.prepare("INSERT OR IGNORE INTO notifications(id,user_id,type,title,body,reference_id,event_key) VALUES(?,?,'referral_reward','Referral milestone reached',?,?,?)").bind(id(),inviterId,body,rewardKey,rewardKey)
  ]);
 }
}
async function syncCommunityLeader(userId:string,env:Env){
 const settings=await env.DB.prepare("SELECT personal_leader_threshold,hybrid_personal_threshold,branch_leader_threshold,active_ratio_min,recovery_days FROM community_leader_settings WHERE id=1").first<{personal_leader_threshold:number;hybrid_personal_threshold:number;branch_leader_threshold:number;active_ratio_min:number;recovery_days:number}>();
 const personalThreshold=Number(settings?.personal_leader_threshold)||500,hybridThreshold=Number(settings?.hybrid_personal_threshold)||250,branchThreshold=Number(settings?.branch_leader_threshold)||500,minActive=Number(settings?.active_ratio_min)||35,recoveryDays=Number(settings?.recovery_days)||14;
 const counts=await env.DB.prepare("WITH RECURSIVE branch(user_id) AS (SELECT invitee_user_id FROM referrals WHERE inviter_user_id=? AND qualified_at IS NOT NULL UNION SELECT r.invitee_user_id FROM referrals r JOIN branch b ON r.inviter_user_id=b.user_id WHERE r.qualified_at IS NOT NULL) SELECT (SELECT COUNT(*) FROM referrals WHERE inviter_user_id=? AND qualified_at IS NOT NULL) AS personal,(SELECT COUNT(*) FROM branch) AS branch,(SELECT COUNT(*) FROM branch b WHERE EXISTS(SELECT 1 FROM member_activity_events a WHERE a.user_id=b.user_id AND julianday(a.occurred_at)>julianday('now','-30 days'))) AS active").bind(userId,userId).first<{personal:number;branch:number;active:number}>();
 const personal=Number(counts?.personal)||0,branch=Number(counts?.branch)||0,active=Number(counts?.active)||0;
 if(!(personal>=personalThreshold||(personal>=hybridThreshold&&branch>=branchThreshold)))return;
 await env.DB.prepare("INSERT OR IGNORE INTO community_leaders(user_id,personal_qualified_count,branch_qualified_count,active_member_count,active_ratio,status,low_activity_since) VALUES(?,?,?,?,?,'recovering',CURRENT_TIMESTAMP)").bind(userId,personal,branch,active,branch?active/branch*100:0).run();
 const existing=await env.DB.prepare("SELECT status,low_activity_since FROM community_leaders WHERE user_id=?").bind(userId).first<{status:string;low_activity_since:string|null}>(),ratio=branch?active/branch*100:0;
 if(ratio>=minActive){await env.DB.prepare("UPDATE community_leaders SET personal_qualified_count=?,branch_qualified_count=?,active_member_count=?,active_ratio=?,status='active',low_activity_since=NULL,updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(personal,branch,active,ratio,userId).run();return;}
 const overdue=!!existing?.low_activity_since&&(Date.now()-Date.parse(existing.low_activity_since+"Z"))>=recoveryDays*86400000,status=overdue?"suspended":"recovering";
 await env.DB.prepare("UPDATE community_leaders SET personal_qualified_count=?,branch_qualified_count=?,active_member_count=?,active_ratio=?,status=?,low_activity_since=COALESCE(low_activity_since,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP WHERE user_id=?").bind(personal,branch,active,ratio,status,userId).run();
}
async function syncCommunityLeaderAncestors(userId:string,env:Env){
 const rows=await env.DB.prepare("WITH RECURSIVE ancestors(user_id,depth) AS (SELECT inviter_user_id,1 FROM referrals WHERE invitee_user_id=? AND qualified_at IS NOT NULL UNION ALL SELECT r.inviter_user_id,a.depth+1 FROM ancestors a JOIN referrals r ON r.invitee_user_id=a.user_id WHERE r.qualified_at IS NOT NULL AND a.depth<100) SELECT user_id,MIN(depth) AS depth FROM ancestors GROUP BY user_id ORDER BY depth").bind(userId).all<{user_id:string;depth:number}>();
 for(const row of rows.results)await syncCommunityLeader(row.user_id,env);
}
