 if(path==="/api/admin/telegram-broadcast"&&request.method==="POST"){
  if(!sameOrigin(request))return json({error:"Request origin could not be verified."},403);
  const admin=await editorialAdmin(request,env);if(!admin)return json({error:"A valid browser administrator session is required."},401);
  if(!env.TELEGRAM_BOT_TOKEN)return json({error:"Telegram bot messaging is not configured."},503);
  try{
   const body=await request.json() as {message?:unknown;after_id?:unknown};
   const message=typeof body.message==="string"?body.message.trim():"",afterId=typeof body.after_id==="string"?body.after_id:"";
   if(message.length<2||message.length>3500)return json({error:"Write a broadcast message between 2 and 3,500 characters."},400);
   const rows=await env.DB.prepare("SELECT telegram_user_id FROM telegram_bot_members WHERE broadcast_opt_in=1 AND telegram_user_id>? ORDER BY telegram_user_id LIMIT 20").bind(afterId).all<{telegram_user_id:string}>();
   let sent=0,failed=0,removed=0;
   for(const row of rows.results){
    try{
     const response=await fetch("https://api.telegram.org/bot"+env.TELEGRAM_BOT_TOKEN+"/sendMessage",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({chat_id:row.telegram_user_id,text:message,disable_web_page_preview:true})});
     const result=await response.json() as {ok?:boolean;error_code?:number};
     if(response.ok&&result.ok===true)sent++;
     else{failed++;if(result.error_code===403){await env.DB.prepare("UPDATE telegram_bot_members SET broadcast_opt_in=0,stopped_at=COALESCE(stopped_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP WHERE telegram_user_id=?").bind(row.telegram_user_id).run();removed++;}}
    }catch{failed++;}
   }
   const next=rows.results.length?rows.results[rows.results.length-1].telegram_user_id:afterId;
   const more=rows.results.length===20?await env.DB.prepare("SELECT telegram_user_id FROM telegram_bot_members WHERE broadcast_opt_in=1 AND telegram_user_id>? ORDER BY telegram_user_id LIMIT 1").bind(next).first():null;
   return json({sent,failed,removed,next_cursor:more?next:null,done:!more});
  }catch{return json({error:"The Telegram broadcast batch could not be sent."},503);}
 }
